import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
def transform(grid):
    h=len(grid); w=len(grid[0])
    out=[row[:] for row in grid]
    centers=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==2:
                n=sum(1 for di,dj in((1,0),(-1,0),(0,1),(0,-1))
                      if 0<=i+di<h and 0<=j+dj<w and grid[i+di][j+dj]==3)
                if n>=2: centers.append((i,j))
    for i,j in centers:
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            if 0<=i+di<h and 0<=j+dj<w: out[i+di][j+dj]=1
    for i,j in centers: out[i][j]=2
    return out
